    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                 const actualValue = current[0];
                 if (typeof actualValue === 'boolean') {
                     return actualValue;
                 }
                 return String(actualValue);
            } else {
                return defaultValue;
            }
        }
        if (typeof current === 'boolean') {
            return current;
        }
        return String(current);
    }

    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);

        if (!valueMainDisplay) {
            return;
        }

        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let numericValue = min;
        let descriptionText = "";

        const descriptionMatch = String(fullDisplayString).match(/\((.+)\)$/);
        if (descriptionMatch && descriptionMatch[1]) {
            descriptionText = descriptionMatch[1];
            fullDisplayString = String(fullDisplayString).substring(0, descriptionMatch.index).trim();
        }

        const valueMatch = String(fullDisplayString).match(/(-?\d+(\.\d+)?)(?=[^\d.]*$|->)/);
         if (valueMatch) {
            numericValue = parseFloat(valueMatch[1]);
            const parts = String(fullDisplayString).split('->');
            valueMainDisplay.innerText = parts.length > 1 ? parts[1].trim() : parts[0].trim();
         } else if (!isNaN(parseFloat(fullDisplayString))) {
             numericValue = parseFloat(fullDisplayString);
             valueMainDisplay.innerText = fullDisplayString;
         } else {
             if (Array.isArray(rawValueFromCharacterData) && typeof rawValueFromCharacterData[0] === 'number') {
                 numericValue = rawValueFromCharacterData[0];
                 valueMainDisplay.innerText = String(numericValue);
             } else if (typeof rawValueFromCharacterData === 'number' || typeof rawValueFromCharacterData === 'string') {
                 valueMainDisplay.innerText = String(rawValueFromCharacterData);
             } else {
                 valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
             }
         }

        if (valueDescDisplay) {
            valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : "";
        }

        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            if(color) {
                progressBar.style.backgroundColor = color;
            } else {
                progressBar.style.backgroundColor = 'var(--accent-highlight)';
            }
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                return;
            }

            const characterKey = "小鞠知花";

            if (characterData.hasOwnProperty(characterKey)) {
                // 好感度
                updateProgressBar(
                    'komari-affection-bar',
                    'komari-affection',
                    'komari-affection-desc',
                    SafeGetValue(characterData, `${characterKey}.好感度`),
                    0,
                    100,
                    'var(--accent-highlight)'
                );

                // 信任度
                updateProgressBar(
                    'komari-trust-bar',
                    'komari-trust',
                    'komari-trust-desc',
                    SafeGetValue(characterData, `${characterKey}.信任度`),
                    0,
                    100,
                    '#7e57c2'
                );

                // 欲望值
                updateProgressBar(
                    'komari-desire-bar',
                    'komari-desire',
                    'komari-desire-desc',
                    SafeGetValue(characterData, `${characterKey}.欲望值`),
                    0,
                    100,
                    '#e74c3c'
                );

                // 敏感度
                updateProgressBar(
                    'komari-sensitivity-bar',
                    'komari-sensitivity',
                    'komari-sensitivity-desc',
                    SafeGetValue(characterData, `${characterKey}.敏感度`),
                    0,
                    100,
                    '#3498db'
                );

                // 心情值（文本型）
                const moodElement = document.getElementById('komari-mood');
                if (moodElement) {
                    moodElement.innerText = SafeGetValue(characterData, `${characterKey}.心情值`, "未知心情");
                }

                // 关系阶段（文本型）
                const relationshipElement = document.getElementById('komari-relationship');
                if (relationshipElement) {
                    relationshipElement.innerText = SafeGetValue(characterData, `${characterKey}.关系`, "未定义关系");
                }

                // 动态确定当前阶段
                const phaseElement = document.getElementById('komari-phase');
                if (phaseElement) {
                    const affection = parseFloat(SafeGetValue(characterData, `${characterKey}.好感度`, 0));
                    const trust = parseFloat(SafeGetValue(characterData, `${characterKey}.信任度`, 0));
                    const desire = parseFloat(SafeGetValue(characterData, `${characterKey}.欲望值`, 0));
                    const sensitivity = parseFloat(SafeGetValue(characterData, `${characterKey}.敏感度`, 0));

                    // 根据分阶段人设定义判断当前阶段
                    if (affection >= 90 && trust >= 85 && desire >= 60 && sensitivity >= 30 && sensitivity <= 60) {
                        phaseElement.innerText = "【完美恋情期】极高好感度 + 极高信任度 + 高欲望值 + 适中敏感度";
                    } else if (affection >= 80 && desire >= 70 && sensitivity < 30) {
                        phaseElement.innerText = "【主导女王期】极高好感度 + 高欲望值 + 低敏感度";
                    } else if (affection >= 70 && trust >= 60 && sensitivity <= 50) {
                        phaseElement.innerText = "【和谐恋情期】高好感度 + 高信任度 + 适中敏感度";
                    } else if (affection >= 60 && trust < 30 && sensitivity >= 70) {
                        phaseElement.innerText = "【痛苦内耗期】高好感度 + 低信任度 + 高敏感度";
                    } else if (affection >= 50 && trust >= 70 && desire <= 20) {
                        phaseElement.innerText = "【纯真依赖期】适中好感度 + 高信任度 + 低欲望值";
                    } else if (desire >= 60 && trust < 40 && sensitivity >= 60) {
                        phaseElement.innerText = "【危险占有期】高欲望值 + 低信任度 + 高敏感度";
                    } else if (trust >= 50 && desire < 15 && sensitivity >= 70) {
                        phaseElement.innerText = "【玻璃心友谊期】适中信任度 + 极低欲望值 + 高敏感度";
                    } else if (affection >= 40 && affection < 60 && desire >= 40 && trust < 50) {
                        phaseElement.innerText = "【暧昧混乱期】中等好感度 + 高欲望值 + 低信任度";
                    } else if (affection < 30 && sensitivity >= 80) {
                        phaseElement.innerText = "【防御过敏期】低好感度 + 极高敏感度";
                    } else {
                        phaseElement.innerText = "基础状态 - 按照基本性格特征与长崎薰互动";
                    }
                }
            } else {
                // 如果角色数据不存在，设置默认值
                const affectionMain = document.getElementById('komari-affection');
                const affectionDesc = document.getElementById('komari-affection-desc');
                const trustMain = document.getElementById('komari-trust');
                const trustDesc = document.getElementById('komari-trust-desc');
                const desireMain = document.getElementById('komari-desire');
                const desireDesc = document.getElementById('komari-desire-desc');
                const sensitivityMain = document.getElementById('komari-sensitivity');
                const sensitivityDesc = document.getElementById('komari-sensitivity-desc');

                if(affectionMain) affectionMain.innerText = 'N/A';
                if(affectionDesc) affectionDesc.innerText = '';
                if(trustMain) trustMain.innerText = 'N/A';
                if(trustDesc) trustDesc.innerText = '';
                if(desireMain) desireMain.innerText = 'N/A';
                if(desireDesc) desireDesc.innerText = '';
                if(sensitivityMain) sensitivityMain.innerText = 'N/A';
                if(sensitivityDesc) sensitivityDesc.innerText = '';

                const moodElement = document.getElementById('komari-mood');
                if(moodElement) moodElement.innerText = '数据未加载';

                const relationshipElement = document.getElementById('komari-relationship');
                if(relationshipElement) relationshipElement.innerText = '数据未加载';

                const phaseElement = document.getElementById('komari-phase');
                if(phaseElement) phaseElement.innerText = '数据未加载';

                const affectionBar = document.getElementById('komari-affection-bar');
                if(affectionBar) affectionBar.style.width = '0%';

                const trustBar = document.getElementById('komari-trust-bar');
                if(trustBar) trustBar.style.width = '0%';

                const desireBar = document.getElementById('komari-desire-bar');
                if(desireBar) desireBar.style.width = '0%';

                const sensitivityBar = document.getElementById('komari-sensitivity-bar');
                if(sensitivityBar) sensitivityBar.style.width = '0%';
            }
        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
